package org.brightstats.desktop;
import java.util.*;import com.google.gson.*;import javafx.scene.control.*;import javafx.scene.layout.*;import javafx.geometry.Insets;import javafx.stage.Window;import org.brightstats.stats.*;import org.brightstats.data.*;
final class BayesianDialog {
 private BayesianDialog(){}
 record Settings(SemModel.Model model,BayesianSem.Options options){Settings{Objects.requireNonNull(model);Objects.requireNonNull(options);}}
 static Settings read(JsonElement value){if(value==null||value.isJsonNull())return null;var o=StatisticalInput.object(value,Set.of("model","options"),"Bayesian studio settings",false);return new Settings(SemModelInput.model(o.get("model")),BayesianInput.options(o.get("options")));}
 static Optional<Settings> show(Window owner,SemModel.Model model,BayesianSem.Options previous){return new Editor(owner,model,previous).dialog.showAndWait();}
 private static final class Editor {
  final Dialog<Settings> dialog=new Dialog<>();final CheckBox reviewed=new CheckBox("I have reviewed the prior distributions, units, bounds and model assumptions");final TextField chains=new TextField("4"),warmup=new TextField("1000"),draws=new TextField("2000"),seed=new TextField("42"),confidence=new TextField("0.95"),predictive=new TextField("100");final Label error=new Label();Settings result;
  Editor(Window owner,SemModel.Model model,BayesianSem.Options previous){dialog.initOwner(owner);dialog.setTitle("Bayesian SEM studio");dialog.setResizable(true);dialog.getDialogPane().getButtonTypes().setAll(ButtonType.OK,ButtonType.CANCEL);if(previous!=null){chains.setText(Integer.toString(previous.chains()));warmup.setText(Integer.toString(previous.warmup()));draws.setText(Integer.toString(previous.draws()));seed.setText(Long.toString(previous.seed()));confidence.setText(Double.toString(previous.confidence()));predictive.setText(Integer.toString(previous.predictiveDraws()));}Map<String,BayesianSem.Prior> old=new HashMap<>();if(previous!=null)previous.priors().forEach(p->old.put(p.parameter(),p));List<ComboBox<BayesianSem.Family>> families=new ArrayList<>();List<TextField> locations=new ArrayList<>(),scales=new ArrayList<>();GridPane priors=new GridPane();priors.setHgap(10);priors.setVgap(8);priors.addRow(0,new Label("Parameter"),new Label("Prior family"),new Label("Location"),new Label("Scale (SD)"),new Label("Configured raw bounds"));int row=1;for(var parameter:model.parameters()){var prior=old.get(parameter.name());boolean variance=parameter.locations().stream().allMatch(l->l.kind()==SemModel.Kind.COVARIANCE&&l.row()==l.column());ComboBox<BayesianSem.Family> family=new ComboBox<>();family.getItems().setAll(BayesianSem.Family.values());family.setValue(prior==null?(variance?BayesianSem.Family.LOG_NORMAL:BayesianSem.Family.NORMAL):prior.family());TextField location=new TextField(prior==null?(variance?Double.toString(Math.log(parameter.scale())):"0"):Double.toString(prior.location())),scale=new TextField(prior==null?(variance?"1":Double.toString(parameter.scale())):Double.toString(prior.scale()));location.setAccessibleText("Prior location: "+parameter.name());scale.setAccessibleText("Prior scale: "+parameter.name());family.setAccessibleText("Prior family: "+parameter.name());priors.addRow(row++,new Label(parameter.name()),family,location,scale,new Label(Objects.toString(parameter.lower(),"−∞")+" to "+Objects.toString(parameter.upper(),"∞")));families.add(family);locations.add(location);scales.add(scale);}
   Label note=new Label("Native independent-chain component-wise Metropolis with warmup-only adaptation. Normal location/scale are raw-unit mean/SD. Log-normal location/scale describe log(raw parameter). Suggested priors use template scales and are not automatically noninformative; edit them for your scientific question. The joint prior is restricted by model bounds and admissibility. Examine traces, rank/folded R-hat, ESS and prior/posterior predictive checks before trusting summaries. This sampler may mix slowly in correlated SEM.");note.setWrapText(true);note.setMaxWidth(930);GridPane settings=new GridPane();settings.setHgap(12);settings.setVgap(8);TextField[] fields={chains,warmup,draws,seed,confidence,predictive};String[] labels={"Independent chains (2–4)","Warmup iterations per chain","Retained unthinned draws per chain","Seed","Credible interval probability","Prior / posterior predictive replications"};for(int i=0;i<fields.length;i++){settings.addRow(i,new Label(labels[i]),fields[i]);fields[i].setAccessibleText(labels[i]);}VBox content=new VBox(14,note,priors,new Separator(),settings,reviewed,error);content.setPadding(new Insets(14));ScrollPane scroll=new ScrollPane(content);scroll.setFitToWidth(true);scroll.setPrefViewportWidth(980);scroll.setPrefViewportHeight(620);dialog.getDialogPane().setContent(scroll);dialog.getDialogPane().lookupButton(ButtonType.OK).addEventFilter(javafx.event.ActionEvent.ACTION,event->{try{if(!reviewed.isSelected())throw new IllegalArgumentException("Review and confirm the prior distributions before sampling.");List<BayesianSem.Prior> selected=new ArrayList<>();for(int j=0;j<families.size();j++)selected.add(new BayesianSem.Prior(model.parameters().get(j).name(),families.get(j).getValue(),Double.parseDouble(locations.get(j).getText().strip()),Double.parseDouble(scales.get(j).getText().strip())));result=new Settings(model,new BayesianSem.Options(selected,Integer.parseInt(chains.getText().strip()),Integer.parseInt(warmup.getText().strip()),Integer.parseInt(draws.getText().strip()),Long.parseLong(seed.getText().strip()),Double.parseDouble(confidence.getText().strip()),Integer.parseInt(predictive.getText().strip())));}catch(RuntimeException invalid){error.setText(invalid.getMessage());event.consume();}});dialog.setResultConverter(button->button==ButtonType.OK?result:null);
  }
 }
 static Settings smoke(Window owner,Settings current){var editor=new Editor(owner,current.model(),current.options());editor.dialog.show();((Button)editor.dialog.getDialogPane().lookupButton(ButtonType.OK)).fire();if(!editor.dialog.isShowing())throw new AssertionError("Unreviewed priors accepted");editor.reviewed.setSelected(true);editor.chains.setText("1");((Button)editor.dialog.getDialogPane().lookupButton(ButtonType.OK)).fire();if(!editor.dialog.isShowing())throw new AssertionError("Single-chain inference accepted");editor.chains.setText(Integer.toString(current.options().chains()));((Button)editor.dialog.getDialogPane().lookupButton(ButtonType.OK)).fire();return Objects.requireNonNull(editor.dialog.getResult());}
}
